window.EditableMathsPilot=Object.assign(window.EditableMathsPilot||{},{"WV-MATHS-SPECIALIST-2019-ASSUMED-Q11":{"question":"<p>The slope field dy/dx = x/(2y + 2) is shown.</p>","parts":[{"label":"(a)","text":"<p>Calculate the slope at (2, 0).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Draw the solution curve through (2, 0).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(c)","text":"<p>Determine its equation.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Slope = 1.</td><td>1</td></tr><tr><td>(b)</td><td>Correct right-hand hyperbola branch through (2, 0), consistent with the field.</td><td>1</td></tr><tr><td>(b)</td><td>Shows symmetry about y = −1 for the implicit curve and vertical tangent there.</td><td>1</td></tr><tr><td>(c)</td><td>Separates (2y + 2)dy = x dx.</td><td>1</td></tr><tr><td>(c)</td><td>Integrates y<sup>2</sup> + 2y = x<sup>2</sup>/2 + C.</td><td>1</td></tr><tr><td>(c)</td><td>Uses (2, 0): y<sup>2</sup> + 2y = x<sup>2</sup>/2 − 2.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-ASSUMED-Q16":{"question":"<p>A fly follows r(t) = (sin t, sin 2t, cos t) metres, 0 ≤ t ≤ 2π seconds, starting at A on the diagram.</p>","parts":[{"label":"(a)","text":"<p>Determine the initial acceleration vector and indicate it on the diagram.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Calculate path length to 0.001 metres.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Differentiates r to v = (cos t, 2cos 2t, −sin t).</td><td>1</td></tr><tr><td>(a)</td><td>Differentiates to acceleration (−sin t, −4sin 2t, −cos t).</td><td>1</td></tr><tr><td>(a)</td><td>Initial acceleration (0, 0, −1) m/second<sup>2</sup>, vertically downwards at A.</td><td>1</td></tr><tr><td>(b)</td><td>Uses ∫<sub>0</sub><sup>2π</sup>√(1 + 4cos<sup>2</sup>2t)dt.</td><td>1</td></tr><tr><td>(b)</td><td>Length ≈ 10.541 m.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-ASSUMED-Q15":{"question":"<p>The curve x<sup>3</sup> + 8y = 64 and its tangent at T(2, 7) are shown. The tangent meets the curve again at P.</p>","parts":[{"label":"(a)","text":"<p>Determine the tangent equation.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the shaded area.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Rotate the region about the x-axis. Calculate its volume to 0.01 cubic units.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Differentiates y = 8 − x<sup>3</sup>/8 to obtain slope −3/2 at T.</td><td>1</td></tr><tr><td>(a)</td><td>Tangent y = 10 − 3x/2.</td><td>1</td></tr><tr><td>(b)</td><td>Finds second intersection x = −4.</td><td>1</td></tr><tr><td>(b)</td><td>Sets ∫<sub>−4</sub><sup>2</sup>[(10 − 3x/2) − (8 − x<sup>3</sup>/8)]dx.</td><td>1</td></tr><tr><td>(b)</td><td>Area = 27/2.</td><td>1</td></tr><tr><td>(c)</td><td>Uses washer integral π∫<sub>−4</sub><sup>2</sup>[(10 − 3x/2)<sup>2</sup> − (8 − x<sup>3</sup>/8)<sup>2</sup>]dx.</td><td>1</td></tr><tr><td>(c)</td><td>Correct squared-function difference and evaluation.</td><td>1</td></tr><tr><td>(c)</td><td>Volume = 2052π/7 ≈ 920.93 cubic units.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2022-FREE-Q07":{"question":"<p>The curve 2x = tan y, its tangent at x = 0 and y = π/3 are shown.</p>","parts":[{"label":"(a)","text":"<p>Use implicit differentiation to determine the tangent at x = 0.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Write an expression for the shaded area.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Evaluate that area exactly.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Differentiates 2 = sec<sup>2</sup>y(dy/dx).</td><td>1</td></tr><tr><td>(a)</td><td>At (0, 0), dy/dx = 2.</td><td>1</td></tr><tr><td>(a)</td><td>Tangent y = 2x.</td><td>1</td></tr><tr><td>(b)</td><td>Uses x = ½tan y and x = y/2.</td><td>1</td></tr><tr><td>(b)</td><td>Sets ½∫<sub>0</sub><sup>π/3</sup>(tan y − y)dy.</td><td>1</td></tr><tr><td>(c)</td><td>Uses ∫tan y dy = −ln|cos y|.</td><td>1</td></tr><tr><td>(c)</td><td>Antiderivative −½ln|cos y| − y<sup>2</sup>/4.</td><td>1</td></tr><tr><td>(c)</td><td>Area = ½ln 2 − π<sup>2</sup>/36.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2018-ASSUMED-Q14":{"question":"<p>The table studies (a<sup>h</sup> − 1)/h as h approaches zero.</p><table><tr><th>h</th><th>a = 2.60</th><th>a = 2.70</th><th>a = 2.72</th><th>a = 2.80</th></tr><tr><td>0.1</td><td>1.00265</td><td></td><td>1.05241</td><td>1.08449</td></tr><tr><td>0.001</td><td>0.95597</td><td>0.99375</td><td></td><td></td></tr><tr><td>0.00001</td><td>0.95552</td><td></td><td></td><td>1.02962</td></tr></table><p></p>","parts":[{"label":"(a)","text":"<p>Complete the table to five decimal places.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Given d(a<sup>x</sup>)/dx = a<sup>x</sup> lim<sub>h→0</sub>(a<sup>h</sup> − 1)/h, what exact a gives derivative a<sup>x</sup>? Explain using the definition and table.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Missing entries: h = 0.1, a = 2.70: 1.04425; h = 0.001, a = 2.72: 1.00113, a = 2.80: 1.03015; h = 0.00001, a = 2.70: 0.99326, a = 2.72: 1.00064. Award 2 for completion under the source rubric.</td><td>2</td></tr><tr><td>(b)</td><td>Exact value a = e.</td><td>1</td></tr><tr><td>(b)</td><td>The required limit must equal 1.</td><td>1</td></tr><tr><td>(b)</td><td>The table brackets a near 2.71828, consistent with a = e.</td><td>1</td></tr></tbody></table>","diagram":"","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-FREE-Q04":{"question":"<p>The graph y = ln x is shown.</p>","parts":[{"label":"(a)(i)","text":"<p>Estimate p if 1.4 = ln p.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Estimate p if e<sup>p+1</sup> − 3 = 0.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Sketch y = ln(x − 2) + 1.</p>","marks":3,"lines":9,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>p ≈ 4 (about 4.05).</td><td>1</td></tr><tr><td>(a)(ii)</td><td>Rearranges p + 1 = ln 3.</td><td>1</td></tr><tr><td>(a)(ii)</td><td>Reads ln 3 ≈ 1.1, hence p ≈ 0.1.</td><td>1</td></tr><tr><td>(b)</td><td>Vertical asymptote x = 2.</td><td>1</td></tr><tr><td>(b)</td><td>Shows point (3, 1).</td><td>1</td></tr><tr><td>(b)</td><td>Correct logarithmic shape shifted right 2 and up 1.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-ASSUMED-Q11":{"question":"<p>The slope field is dy/dx = kxy, where k is constant.</p>","parts":[{"label":"(a)","text":"<p>Slope at (1, 2) is −4. Determine k.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine and draw the solution through (1, 2).</p>","marks":3,"lines":9,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Substitutes −4 = 2k.</td><td>1</td></tr><tr><td>(a)</td><td>k = −2.</td><td>1</td></tr><tr><td>(b)</td><td>Separates and integrates ln|y| = −x<sup>2</sup> + C.</td><td>1</td></tr><tr><td>(b)</td><td>Uses (1, 2) to obtain y = 2e<sup>1−x²</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Correct bell-shaped curve through (1, 2), symmetric about the y-axis.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2017-FREE-Q04":{"question":"<p>f(x) = 1 − √(x − 4) is graphed.</p>","parts":[{"label":"(a)","text":"<p>Sketch y = f<sup>−1</sup>(x).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Determine its rule and domain.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>If g(x) = 1/x<sup>2</sup>, determine f ∘ g(x).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine the domain of f ∘ g.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Reflects the graph in y = x.</td><td>1</td></tr><tr><td>(a)</td><td>Includes points (1, 4), (0, 5) and (−1, 8).</td><td>1</td></tr><tr><td>(b)</td><td>Interchanges variables and rearranges √(y − 4) = 1 − x.</td><td>1</td></tr><tr><td>(b)</td><td>f<sup>−1</sup>(x) = (1 − x)<sup>2</sup> + 4.</td><td>1</td></tr><tr><td>(b)</td><td>Domain x ≤ 1.</td><td>1</td></tr><tr><td>(c)</td><td>f(g(x)) = 1 − √(1/x<sup>2</sup> − 4).</td><td>1</td></tr><tr><td>(d)</td><td>Requires x ≠ 0 and 1/x<sup>2</sup> − 4 ≥ 0.</td><td>1</td></tr><tr><td>(d)</td><td>Obtains |x| ≤ ½.</td><td>1</td></tr><tr><td>(d)</td><td>Domain [−½, 0) ∪ (0, ½].</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2021-ASSUMED-Q18":{"question":"<p>The curve is x<sup>3</sup> + y<sup>3</sup> = 3xy + y.</p>","parts":[{"label":"(a)","text":"<p>Use implicit differentiation to obtain dy/dx.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>The slope is zero at O, A and B. Show the x-coordinates of A and B satisfy x<sup>4</sup> − 2x − 1 = 0, and find A to 0.001.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Differentiates 3x<sup>2</sup> + 3y<sup>2</sup>y′ = 3y + 3xy′ + y′.</td><td>1</td></tr><tr><td>(a)</td><td>Collects the y′ terms.</td><td>1</td></tr><tr><td>(a)</td><td>y′ = (3y − 3x<sup>2</sup>)/(3y<sup>2</sup> − 3x − 1).</td><td>1</td></tr><tr><td>(b)</td><td>Zero slope gives y = x<sup>2</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Substitutes to obtain x<sup>2</sup>(x<sup>4</sup> − 2x − 1) = 0; excludes O.</td><td>1</td></tr><tr><td>(b)</td><td>A ≈ (−0.475, 0.225).</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-FREE-Q03":{"question":"<p>Consider f(x) = (x − 1)<sup>2</sup>/e<sup>x</sup>.</p>","parts":[{"label":"(a)","text":"<p>Show f′(x) = (−x<sup>2</sup> + 4x − 3)/e<sup>x</sup>.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Explain why stationary points occur at x = 1 and x = 3.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Given f″(x) = (x<sup>2</sup> − 6x + 7)/e<sup>x</sup>, classify these points.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses quotient or product rule correctly.</td><td>1</td></tr><tr><td>(a)</td><td>Simplifies to the stated expression.</td><td>1</td></tr><tr><td>(b)</td><td>Factors the numerator as −(x − 1)(x − 3).</td><td>1</td></tr><tr><td>(b)</td><td>Denominator is nonzero, so f′ = 0 at x = 1, 3.</td><td>1</td></tr><tr><td>(c)</td><td>Evaluates f″(1) = 2/e &gt; 0 and f″(3) = −2/e<sup>3</sup> &lt; 0.</td><td>1</td></tr><tr><td>(c)</td><td>x = 1 is a local minimum.</td><td>1</td></tr><tr><td>(c)</td><td>x = 3 is a local maximum.</td><td>1</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-ASSUMED-Q14":{"question":"<p>The graph of y = f(x) is shown.</p>","parts":[{"label":"(a)","text":"<p>Sketch y = 1/f(x) on the supplied axes.</p>","marks":4,"lines":12,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Sketch y = f(−|x|) on the supplied axes.</p>","marks":3,"lines":9,"space":"drawing","diagram":""},{"label":"(c)","text":"<p>Solve |f(x) − 1| = 1.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Shows vertical asymptotes x = −1 and x = 1; correct finite endpoints and (0, ½), with open point (0, −1); correct reciprocal branches. Award one per feature.</td><td>4</td></tr><tr><td>(b)</td><td>Uses the original branch for −2 ≤ x &lt; 0; reflects it in the y-axis for x &gt; 0; includes the isolated point (0, 2). Award one per feature.</td><td>3</td></tr><tr><td>(c)</td><td>Uses f(x) = 0 or f(x) = 2.</td><td>1</td></tr><tr><td>(c)</td><td>x = −1, 0, 1, 2.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-FREE-Q08":{"question":"<p>An isosceles triangle PQR is inscribed in a circle of fixed radius r and centre O. Angle θ is defined in the diagram.</p>","parts":[{"label":"(a)","text":"<p>Show its area A = r<sup>2</sup>sin θ(1 + cos θ).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Use calculus to determine θ maximising A, and state the exact maximum area in terms of r. Justify. You may use sin<sup>2</sup>x = 1 − cos<sup>2</sup>x.</p>","marks":5,"lines":15,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Base = 2r sin θ, height = r(1 + cos θ); uses half base times height.</td><td>2</td></tr><tr><td>(b)</td><td>A′ = r<sup>2</sup>(cos θ + cos<sup>2</sup>θ − sin<sup>2</sup>θ).</td><td>1</td></tr><tr><td>(b)</td><td>Sets 2cos<sup>2</sup>θ + cos θ − 1 = 0.</td><td>1</td></tr><tr><td>(b)</td><td>Valid solution θ = π/3.</td><td>1</td></tr><tr><td>(b)</td><td>Maximum area 3√3 r<sup>2</sup>/4.</td><td>1</td></tr><tr><td>(b)</td><td>Justifies maximum by derivative sign or negative second derivative.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-ASSUMED-Q20":{"question":"<p>The graph of (x<sup>2</sup> + y<sup>2</sup> − 1)<sup>3</sup> = x<sup>2</sup>y<sup>3</sup> is shown.</p>","parts":[{"label":"(a)","text":"<p>Implicitly differentiate to obtain an equation relating x, y and dy/dx. Do not make dy/dx the subject.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the exact tangent slope at L(1, 1).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>At H the curve is horizontal. Determine H to 0.001.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Obtains 3(x<sup>2</sup> + y<sup>2</sup> − 1)<sup>2</sup>(2x + 2yy′) = 2xy<sup>3</sup> + 3x<sup>2</sup>y<sup>2</sup>y′. Award for chain rule, inner derivative and product rule.</td><td>3</td></tr><tr><td>(b)</td><td>Substitutes (1, 1), obtaining 6 + 6y′ = 2 + 3y′.</td><td>1</td></tr><tr><td>(b)</td><td>Slope = −4/3.</td><td>1</td></tr><tr><td>(c)</td><td>Sets y′ = 0 in the derivative equation.</td><td>1</td></tr><tr><td>(c)</td><td>Solves simultaneously with the original curve equation.</td><td>1</td></tr><tr><td>(c)</td><td>H ≈ (0.514, 1.237).</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-ASSUMED-Q12":{"question":"<p>Josie runs for 10 minutes on a treadmill. Her speed is 12.3 km/h for the first 2 minutes, then s(t) = 10 − ln(t − 1.99)/t km/h, where t is minutes after starting.</p>","parts":[{"label":"(a)","text":"<p>Sketch speed versus time for the run.</p>","marks":3,"lines":9,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>When is her speed 10 km/h?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>When is her acceleration zero?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Shows constant speed 12.3 on 0 ≤ t ≤ 2, correct decreasing-then-increasing curve, and correct domain and scale. Award one each.</td><td>3</td></tr><tr><td>(b)</td><td>t = 2.99 minutes.</td><td>1</td></tr><tr><td>(c)</td><td>Throughout the constant-speed interval 0 &lt; t &lt; 2 minutes.</td><td>1</td></tr><tr><td>(c)</td><td>At the minimum of the later speed curve, t ≈ 6.302 minutes.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-ASSUMED-Q12":{"question":"<p>Complex numbers z and w are shown: |z| = 3, Arg(z) = θ, 0 &lt; θ &lt; π/4; w = z − k, where k is real and positive, and Arg(w) = 2θ.</p>","parts":[{"label":"(a)","text":"<p>Represent this information on the Argand diagram.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine a simplified expression for k in terms of θ. Justify.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Labels |z| = 3, the horizontal segment from w to z as k, and angles θ and 2θ at the origin. Award one per feature.</td><td>3</td></tr><tr><td>(b)</td><td>Applies sine rule: k/sin θ = 3/sin(π − 2θ).</td><td>1</td></tr><tr><td>(b)</td><td>Uses sin 2θ = 2sin θ cos θ.</td><td>1</td></tr><tr><td>(b)</td><td>k = 3/(2cos θ).</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2022-ASSUMED-Q10":{"question":"<p>A particle has velocity v(t) = (3sin t, 2cos t), t ≥ 0, and initial position r(0) = (−3, −2). Its path for the first 4 seconds is shown.</p>","parts":[{"label":"(a)(i)","text":"<p>State what ∫<sub>0</sub><sup>1</sup>v(t)dt measures.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>State what ∫<sub>0</sub><sup>2π</sup>|v(t)|dt measures.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine r(t).</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine the Cartesian equation of its path.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>Displacement vector during the first 1 second; award for displacement and interval.</td><td>2</td></tr><tr><td>(a)(ii)</td><td>Total distance travelled during the first 2π seconds; award for distance and interval.</td><td>2</td></tr><tr><td>(b)</td><td>Integrates components to (−3cos t + C₁, 2sin t + C₂).</td><td>1</td></tr><tr><td>(b)</td><td>Initial position gives C₁ = 0, C₂ = −2.</td><td>1</td></tr><tr><td>(b)</td><td>r(t) = (−3cos t, 2sin t − 2).</td><td>1</td></tr><tr><td>(c)</td><td>Uses sin<sup>2</sup>t + cos<sup>2</sup>t = 1.</td><td>1</td></tr><tr><td>(c)</td><td>x<sup>2</sup>/9 + (y + 2)<sup>2</sup>/4 = 1.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2021-ASSUMED-Q16":{"question":"<p>The rectangular prism has A(2, 0, 0), C(0, 4, 0), T(0, 0, 3). M(0, 2, 1.5) is the centre of face OCFT.</p>","parts":[{"label":"(a)","text":"<p>Determine the vector equation of diagonal BT.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the Cartesian equation of the sphere containing all prism vertices.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Prove using vectors that AM does not intersect BT.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>B = (2, 4, 0), direction BT = (−2, −4, 3).</td><td>1</td></tr><tr><td>(a)</td><td>r = (2, 4, 0) + λ(−2, −4, 3).</td><td>1</td></tr><tr><td>(b)</td><td>Centre = (1, 2, 1.5).</td><td>1</td></tr><tr><td>(b)</td><td>Radius squared = 29/4.</td><td>1</td></tr><tr><td>(b)</td><td>(x − 1)<sup>2</sup> + (y − 2)<sup>2</sup> + (z − 1.5)<sup>2</sup> = 29/4.</td><td>1</td></tr><tr><td>(c)</td><td>AM: r = (2, 0, 0) + μ(−2, 2, 1.5).</td><td>1</td></tr><tr><td>(c)</td><td>Equating x gives μ = λ; y gives λ = 2/3.</td><td>1</td></tr><tr><td>(c)</td><td>The z equations would require μ = 2λ, a contradiction. Thus there is no intersection.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2022-FREE-Q06":{"question":"<p>Complex numbers z₁ = 4cis(5π/6) and z₂ are shown on the Argand plane.</p>","parts":[{"label":"(a)","text":"<p>Determine exact polar form for z₂.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Plot w = z₁(z₂)<sup>−1</sup> on the diagram.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>If z₁ solves z<sup>n</sup> = r, with positive real r and positive integer n, determine the smallest r in the form 2<sup>p</sup>. Justify.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Modulus 2√2 and argument 5π/4 (or −3π/4), giving z₂ = 2√2 cis(5π/4).</td><td>2</td></tr><tr><td>(b)</td><td>w = √2 cis(−5π/12).</td><td>1</td></tr><tr><td>(b)</td><td>Cartesian form ((√3 − 1)/2) − ((√3 + 1)/2)i.</td><td>1</td></tr><tr><td>(b)</td><td>Plots in the fourth quadrant at those coordinates.</td><td>1</td></tr><tr><td>(c)</td><td>Positive real requires 5nπ/6 = 2kπ.</td><td>1</td></tr><tr><td>(c)</td><td>Smallest n = 12.</td><td>1</td></tr><tr><td>(c)</td><td>r = 4<sup>12</sup> = 2<sup>24</sup>.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-FREE-Q02":{"question":"","parts":[{"label":"(a)","text":"<p>Solve 4x − y − 2z = 5; 2x + y − z = 4; x − y − z = 3.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Another system is 2x − y − z = 0; x − 2y − z = 2; x − 2y + kz = 6. Its reduction gives x = −2(k − 1)/[3(k + 1)], y = −4(k + 2)/[3(k + 1)], z = 4/(k + 1). Does it have a unique solution for every real k? If not, explain geometrically.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Eliminates one variable correctly.</td><td>1</td></tr><tr><td>(a)</td><td>Continues valid elimination or substitution.</td><td>1</td></tr><tr><td>(a)</td><td>x = −1, y = 1, z = −5.</td><td>1</td></tr><tr><td>(b)</td><td>Unique solution except k = −1.</td><td>1</td></tr><tr><td>(b)</td><td>At k = −1, the last two equations describe distinct parallel planes.</td><td>1</td></tr><tr><td>(b)</td><td>No common point exists; the third plane cuts them in parallel lines.</td><td>1</td></tr></tbody></table>","diagram":"","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2019-ASSUMED-Q16":{"question":"<p>Plane Π₁ has equation z = 2x + y + 4. Line L: r = (2, 0, 3) + λ(1, 2, −1).</p>","parts":[{"label":"(a)","text":"<p>Determine a vector normal to Π₁.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the intersection of L and Π₁.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Plane Π₂ contains L and is perpendicular to Π₁. Determine its vector equation.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Sphere S has |r − (3, 1, 4)| = √35. Is L tangent to S? Justify.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Rewrites plane as 2x + y − z = −4 and identifies normal (2, 1, −1).</td><td>2</td></tr><tr><td>(b)</td><td>Substitutes line coordinates in plane.</td><td>1</td></tr><tr><td>(b)</td><td>Obtains λ = −1.</td><td>1</td></tr><tr><td>(b)</td><td>Intersection (1, −2, 4).</td><td>1</td></tr><tr><td>(c)</td><td>Normal is perpendicular to (1, 2, −1) and (2, 1, −1).</td><td>1</td></tr><tr><td>(c)</td><td>Cross product gives a multiple of (1, 1, 3).</td><td>1</td></tr><tr><td>(c)</td><td>Uses point (2, 0, 3), obtaining constant 11.</td><td>1</td></tr><tr><td>(c)</td><td>r · (1, 1, 3) = 11.</td><td>1</td></tr><tr><td>(d)</td><td>Substitutes line in sphere: 6λ<sup>2</sup> − 4λ − 32 = 0.</td><td>1</td></tr><tr><td>(d)</td><td>Two roots λ = −2 and 8/3.</td><td>1</td></tr><tr><td>(d)</td><td>Two intersections, so L is not tangent.</td><td>1</td></tr></tbody></table>","diagram":"","marks":12,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2019-FREE-Q07":{"question":"<p>The graphs of y = f(|x|) and y = |f(x)| are shown. Given that y = f<sup>−1</sup>(x) is also a function, sketch a possible f(x) and justify your choice.</p>","parts":[{"label":"","text":"","marks":4,"lines":10,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td></td><td>Includes (0, 2), (1.5, 0), (2, −0.5).</td><td>1</td></tr><tr><td></td><td>Uses y = 1.5 − x for 0 &lt; x ≤ 2, open at (0, 1.5).</td><td>1</td></tr><tr><td></td><td>A valid left branch is y = −0.5x − 2 for −2 ≤ x &lt; 0, open at (0, −2).</td><td>1</td></tr><tr><td></td><td>This choice is one-to-one and passes the horizontal line test, so the inverse is a function.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":4,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-FREE-Q06":{"question":"<p>Digitising error X is uniform with density f(x) = 1 for −0.5 &lt; x &lt; 0.5 and zero otherwise.</p>","parts":[{"label":"(a)","text":"<p>Sketch f(x).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Find the probability the error is at least 0.35.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Given a negative error, find the probability it is less than −0.35.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find the probability that the square of the error is less than 0.09.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Calculate the variance.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Shows horizontal density 1 on (−0.5, 0.5), and zero elsewhere.</td><td>2</td></tr><tr><td>(b)</td><td>0.15.</td><td>1</td></tr><tr><td>(c)</td><td>Uses P(X &lt; −0.35)/P(X &lt; 0).</td><td>1</td></tr><tr><td>(c)</td><td>0.15/0.5 = 0.3.</td><td>1</td></tr><tr><td>(d)</td><td>X<sup>2</sup> &lt; 0.09 means −0.3 &lt; X &lt; 0.3.</td><td>1</td></tr><tr><td>(d)</td><td>Probability = 0.6.</td><td>1</td></tr><tr><td>(e)</td><td>Mean = 0 by symmetry.</td><td>1</td></tr><tr><td>(e)</td><td>Uses E(X<sup>2</sup>) = ∫<sub>−0.5</sub><sup>0.5</sup>x<sup>2</sup>dx.</td><td>1</td></tr><tr><td>(e)</td><td>Variance = 1/12.</td><td>1</td></tr></tbody></table>","diagram":"","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-FREE-Q07":{"question":"<p>A company’s profit in millions of dollars is P(t) = 2t sin(3t), 0 ≤ t ≤ 5, with t in years. Its graph is shown.</p>","parts":[{"label":"(a)","text":"<p>Determine marginal profit P′(t).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Calculate the rate of change of marginal profit at t = π/18 years.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Use the increments formula at t = 7π/6 to estimate the change in profit for one month.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses product and chain rules: P′(t) = 2sin(3t) + 6t cos(3t).</td><td>2</td></tr><tr><td>(b)</td><td>Differentiates again: P″(t) = 12cos(3t) − 18t sin(3t).</td><td>2</td></tr><tr><td>(b)</td><td>Substitutes t = π/18.</td><td>1</td></tr><tr><td>(b)</td><td>P″(π/18) = 6√3 − π/2 million dollars/year<sup>2</sup>.</td><td>1</td></tr><tr><td>(c)</td><td>One month is Δt = 1/12 year.</td><td>1</td></tr><tr><td>(c)</td><td>Uses ΔP ≈ P′(7π/6)/12.</td><td>1</td></tr><tr><td>(c)</td><td>Estimated change = −1/6 million dollars, a loss of about $166667.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2022-ASSUMED-Q10":{"question":"<p>A damped spring has displacement x(t) = 3e<sup>−t</sup>sin t cm, t ≥ 0 seconds.</p>","parts":[{"label":"(a)","text":"<p>When does the mass first return to x = 0?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine its velocity.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine its displacement when it first changes direction.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>It is considered stopped when amplitude A(t) = 3e<sup>−t</sup> reaches 0.01 cm. How long does this take?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Sets sin t = 0 and takes first positive root t = π seconds.</td><td>2</td></tr><tr><td>(b)</td><td>Product rule gives v(t) = 3e<sup>−t</sup>(cos t − sin t).</td><td>2</td></tr><tr><td>(c)</td><td>Solves v = 0: tan t = 1.</td><td>1</td></tr><tr><td>(c)</td><td>First positive time t = π/4.</td><td>1</td></tr><tr><td>(c)</td><td>x = (3/√2)e<sup>−π/4</sup> ≈ 0.967 cm.</td><td>1</td></tr><tr><td>(d)</td><td>Solves e<sup>−t</sup> = 1/300.</td><td>1</td></tr><tr><td>(d)</td><td>t = ln 300 ≈ 5.704 seconds.</td><td>1</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-ASSUMED-Q10":{"question":"<p>The complex number w = 4cis(2π/3), together with wz and wz<sup>2</sup>, is shown on the Argand diagram.</p>","parts":[{"label":"(a)","text":"<p>Express wz and wz<sup>2</sup> in exact polar form.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Describe the transformations performed by successive multiplication by z.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine z in exact polar form.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Describe the transformations performed by successive multiplication by z<sup>−1</sup>.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>wz = 2cis(5π/6).</td><td>1</td></tr><tr><td>(a)</td><td>wz<sup>2</sup> = cis π.</td><td>1</td></tr><tr><td>(b)</td><td>Dilation about the origin with scale ½.</td><td>1</td></tr><tr><td>(b)</td><td>Anticlockwise rotation π/6.</td><td>1</td></tr><tr><td>(c)</td><td>z = ½cis(π/6).</td><td>1</td></tr><tr><td>(d)</td><td>Dilation about the origin with scale 2.</td><td>1</td></tr><tr><td>(d)</td><td>Clockwise rotation π/6.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2017-ASSUMED-Q10":{"question":"<p>Consider z = 1 − i shown on the complex plane.</p>","parts":[{"label":"(a)","text":"<p>Express z in polar form.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Express z<sup>2</sup>, z<sup>3</sup>, z<sup>4</sup> in exact polar form.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Sketch these three powers as vectors on the Argand diagram.</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(d)","text":"<p>Describe the transformations performed by successive multiplication by z.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>z = √2 cis(−π/4).</td><td>1</td></tr><tr><td>(b)</td><td>z<sup>2</sup> = 2cis(−π/2), z<sup>3</sup> = 2√2 cis(−3π/4), z<sup>4</sup> = 4cis(−π). Award for moduli and arguments.</td><td>2</td></tr><tr><td>(c)</td><td>Vectors from origin to (0, −2), (−2, −2) and (−4, 0). Award for correct endpoints and vector representation.</td><td>2</td></tr><tr><td>(d)</td><td>Dilation about origin with scale √2.</td><td>1</td></tr><tr><td>(d)</td><td>Clockwise rotation π/4.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2024-ASSUMED-Q16":{"question":"<p>A shampoo bottle has uniform parabolic cross-section y = 20 − (4/5)x<sup>2</sup>, −5 ≤ x ≤ 5. Dimensions are centimetres. The width perpendicular to this section is 4 cm.</p>","parts":[{"label":"(a)","text":"<p>Calculate shampoo volume V when filled to height 10 cm.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>The bottle is inverted and the same shampoo settles as shown. Determine its new level h.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>At y = 10, x = ±5/√2.</td><td>1</td></tr><tr><td>(a)</td><td>Cross-sectional area = 100/√2 + 2∫<sub>5/√2</sub><sup>5</sup>(20 − 4x<sup>2</sup>/5)dx.</td><td>1</td></tr><tr><td>(a)</td><td>Multiplies this area by width 4.</td><td>1</td></tr><tr><td>(a)</td><td>V = (1600 − 400√2)/3 ≈ 344.77 cm<sup>3</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>After inversion uses y = 4x<sup>2</sup>/5, with intersections x = ±√(5h)/2.</td><td>1</td></tr><tr><td>(b)</td><td>Forms volume 4∫<sub>−√(5h)/2</sub><sup>√(5h)/2</sup>(h − 4x<sup>2</sup>/5)dx.</td><td>1</td></tr><tr><td>(b)</td><td>Sets this equal to V from (a).</td><td>1</td></tr><tr><td>(b)</td><td>Solves h ≈ 14.95 cm.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2020-ASSUMED-Q21":{"question":"<p>The graph of y = f(x) is shown. Define N(k) as the number of real solutions to |f(x)| = k, for real k.</p>","parts":[{"label":"","text":"<p>Sketch N(k) on the supplied axes.</p>","marks":5,"lines":12,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td></td><td>N(k) = 0 for k &lt; 0.</td><td>1</td></tr><tr><td></td><td>N(0) = 2.</td><td>1</td></tr><tr><td></td><td>N(k) = 4 for 0 &lt; k &lt; 2.</td><td>1</td></tr><tr><td></td><td>N(2) = 3.</td><td>1</td></tr><tr><td></td><td>N(k) = 2 for k &gt; 2, with correct open and closed endpoints.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-ASSUMED-Q09":{"question":"<p>Fermium-257 decays according to P = P₀e<sup>kt</sup>, with mass P grams, time t days, initial mass P₀ and constant k. Its half-life is 100.5 days.</p>","parts":[{"label":"(a)","text":"<p>Determine k to three significant figures.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>How many days until 100 g first decays below 5 g?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine the rate of change on the day found in (b).</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses ½ = e<sup>100.5k</sup>.</td><td>1</td></tr><tr><td>(a)</td><td>k = ln(½)/100.5.</td><td>1</td></tr><tr><td>(a)</td><td>k ≈ −0.00690 day<sup>−1</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Solves 5 = 100e<sup>kt</sup>, giving t ≈ 434.349 days.</td><td>1</td></tr><tr><td>(b)</td><td>First whole day below 5 g is day 435.</td><td>1</td></tr><tr><td>(c)</td><td>dP/dt = 100ke<sup>kt</sup>.</td><td>1</td></tr><tr><td>(c)</td><td>At day 435, rate ≈ −0.0343 g/day.</td><td>1</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2024-ASSUMED-Q10":{"question":"<p>A circle is drawn in the Argand plane; z is any point on it.</p>","parts":[{"label":"(a)(i)","text":"<p>State the circle equation.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Given a ≤ |z − i| ≤ b, determine exact a and b.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Sketch the intersection of z − z̄ ≤ 6i and π/4 ≤ Arg(z − 1 + i) ≤ 3π/4.</p>","marks":4,"lines":12,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>|z − (1 + i)| = ½; award for centre and radius.</td><td>2</td></tr><tr><td>(a)(ii)</td><td>Distances from i range from ½ to 3/2, hence a = ½ and b = 3/2.</td><td>2</td></tr><tr><td>(b)</td><td>First condition gives y ≤ 3.</td><td>1</td></tr><tr><td>(b)</td><td>Argument wedge has vertex (1, −1).</td><td>1</td></tr><tr><td>(b)</td><td>Boundary rays y = x − 2 and y = −x, directed upward.</td><td>1</td></tr><tr><td>(b)</td><td>Shades their intersection with y ≤ 3; solid included boundaries, vertex excluded because Arg(0) is undefined.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-ASSUMED-Q17":{"question":"<p>Year 12 Methods examination scores X have mean 75 and standard deviation 22.</p>","parts":[{"label":"(a)","text":"<p>Determine E(X + 5).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine Var(25 − 2X).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Scores are scaled using Y = aX + b to mean 60 and standard deviation 15. Determine a and b.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>80.</td><td>1</td></tr><tr><td>(b)</td><td>Uses Var(25 − 2X) = 4Var(X).</td><td>1</td></tr><tr><td>(b)</td><td>Variance = 1936.</td><td>1</td></tr><tr><td>(c)</td><td>Uses |a|22 = 15.</td><td>1</td></tr><tr><td>(c)</td><td>For order-preserving scaling a = 15/22.</td><td>1</td></tr><tr><td>(c)</td><td>Uses 60 = 75a + b.</td><td>1</td></tr><tr><td>(c)</td><td>b = 195/22 ≈ 8.864. A negative a reverses score order; if allowed, a = −15/22 and b = 2445/22.</td><td>1</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2017-FREE-Q07":{"question":"<p>A rectangular prism has square base OADB. O is the origin, A = (4, 0, 0), B = (0, 4, 0), C = (0, 0, c), c &gt; 0.</p>","parts":[{"label":"(a)(i)","text":"<p>Determine a vector equation of the line through A and E in terms of c.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Determine the Cartesian equation of plane ADEC.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine c so that main diagonals AE and BG are perpendicular.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>E = (0, 4, c).</td><td>1</td></tr><tr><td>(a)(i)</td><td>AE = (−4, 4, c).</td><td>1</td></tr><tr><td>(a)(i)</td><td>r = (4, 0, 0) + λ(−4, 4, c).</td><td>1</td></tr><tr><td>(a)(ii)</td><td>Uses two independent vectors in the plane, for example AD = (0, 4, 0) and AC = (−4, 0, c).</td><td>1</td></tr><tr><td>(a)(ii)</td><td>Normal is a multiple of (c, 0, 4).</td><td>1</td></tr><tr><td>(a)(ii)</td><td>Substitutes A to obtain constant 4c.</td><td>1</td></tr><tr><td>(a)(ii)</td><td>cx + 4z = 4c.</td><td>1</td></tr><tr><td>(b)</td><td>BG = (4, −4, c).</td><td>1</td></tr><tr><td>(b)</td><td>Perpendicular requires −32 + c<sup>2</sup> = 0.</td><td>1</td></tr><tr><td>(b)</td><td>c = 4√2 since c &gt; 0.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2024-ASSUMED-Q12":{"question":"<p>A circular log is cut into a square beam of side 40 cm and four sideboards. Variables x and y describe one sideboard as shown.</p>","parts":[{"label":"(a)","text":"<p>Determine the exact radius of the log.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Show that the area of one sideboard is A(x) = 2x√(400 − 40x − x<sup>2</sup>) cm<sup>2</sup>.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Use calculus to determine x and y maximising this area.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses (2r)<sup>2</sup> = 40<sup>2</sup> + 40<sup>2</sup>.</td><td>1</td></tr><tr><td>(a)</td><td>r = 20√2 cm.</td><td>1</td></tr><tr><td>(b)</td><td>Pythagoras gives (y/2)<sup>2</sup> + (20 + x)<sup>2</sup> = 800.</td><td>1</td></tr><tr><td>(b)</td><td>Thus y = 2√(400 − 40x − x<sup>2</sup>).</td><td>1</td></tr><tr><td>(b)</td><td>Area xy gives the stated expression.</td><td>1</td></tr><tr><td>(c)</td><td>Differentiates A: A′ = (800 − 120x − 4x<sup>2</sup>)/√(400 − 40x − x<sup>2</sup>).</td><td>1</td></tr><tr><td>(c)</td><td>Sets derivative zero and obtains x = −15 + 5√17 ≈ 5.616 cm.</td><td>1</td></tr><tr><td>(c)</td><td>Verifies a maximum by sign change or second derivative.</td><td>1</td></tr><tr><td>(c)</td><td>Corresponding y ≈ 24.98 cm.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2024-ASSUMED-Q12":{"question":"<p>The vertical displacement y(t) cm of a merry-go-round horse seat satisfies y″ = −(π<sup>2</sup>/2)y. The total vertical span is 50 cm, and the seat starts at its mean position.</p>","parts":[{"label":"(a)","text":"<p>Determine y(t).</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine maximum vertical speed to the nearest cm/second.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Angular frequency π/√2.</td><td>1</td></tr><tr><td>(a)</td><td>Amplitude 25 cm.</td><td>1</td></tr><tr><td>(a)</td><td>y(t) = 25sin(πt/√2), or its negative depending on initial direction.</td><td>1</td></tr><tr><td>(b)</td><td>Maximum speed is amplitude times angular frequency.</td><td>1</td></tr><tr><td>(b)</td><td>25π/√2 ≈ 56 cm/second.</td><td>1</td></tr></tbody></table>","diagram":"","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2020-FREE-Q05":{"question":"<p>The graph f(x) = 1 − |x + 1|/2 is shown.</p>","parts":[{"label":"(a)","text":"<p>Sketch g(x) = 1/f(x).</p>","marks":4,"lines":12,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Give the domain and range of h(x) = 4/(2 − |x + 1|).</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Vertical asymptotes x = −3 and x = 1.</td><td>1</td></tr><tr><td>(a)</td><td>Shows (−1, 1) as the central minimum.</td><td>1</td></tr><tr><td>(a)</td><td>Shows (0, 2), no x-intercepts and horizontal asymptote y = 0.</td><td>1</td></tr><tr><td>(a)</td><td>Correct positive central branch and two negative outer branches.</td><td>1</td></tr><tr><td>(b)</td><td>Domain R excluding −3 and 1.</td><td>1</td></tr><tr><td>(b)</td><td>Range includes y &lt; 0.</td><td>1</td></tr><tr><td>(b)</td><td>Other range component y ≥ 2; thus (−∞, 0) ∪ [2, ∞).</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2017-ASSUMED-Q20":{"question":"<p>A model train has acceleration a(t) = pt − 13 cm/second<sup>2</sup>, 0 ≤ t ≤ 10. Initial velocity is 5 cm/second; displacement at 2 seconds is −50 cm and at 6 seconds is 178 cm.</p>","parts":[{"label":"(a)","text":"<p>Determine its initial acceleration.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine p.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(c)","text":"<p>When is the train at rest?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>How far has it travelled when acceleration is 47 cm/second<sup>2</sup>?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>−13 cm/second<sup>2</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Integrates v = pt<sup>2</sup>/2 − 13t + 5.</td><td>1</td></tr><tr><td>(b)</td><td>Integrates s = pt<sup>3</sup>/6 − 13t<sup>2</sup>/2 + 5t + C.</td><td>1</td></tr><tr><td>(b)</td><td>Uses s(2) = −50 and s(6) = 178 to form simultaneous equations.</td><td>1</td></tr><tr><td>(b)</td><td>p = 12 and C = −60.</td><td>1</td></tr><tr><td>(c)</td><td>Solves 6t<sup>2</sup> − 13t + 5 = 0.</td><td>1</td></tr><tr><td>(c)</td><td>t = ½ and 5/3 seconds.</td><td>1</td></tr><tr><td>(d)</td><td>Acceleration 47 occurs at t = 5.</td><td>1</td></tr><tr><td>(d)</td><td>Distance ∫<sub>0</sub><sup>5</sup>|6t<sup>2</sup> − 13t + 5|dt ≈ 115.68 cm, splitting at both rest times.</td><td>1</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-ASSUMED-Q18":{"question":"<p>A building has five alarms; the system works if at least two work. Each alarm fails overnight with probability 0.05. X is the number failing overnight.</p>","parts":[{"label":"(a)","text":"<p>State the distribution of X.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>State the assumptions required.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find the probability the system fails overnight.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>One alarm is removed for maintenance. Find the probability the system still works in the morning.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>X ~ Bin(5, 0.05); award for distribution and parameters.</td><td>2</td></tr><tr><td>(b)</td><td>Alarm failures are independent.</td><td>1</td></tr><tr><td>(b)</td><td>Each has the same failure probability 0.05.</td><td>1</td></tr><tr><td>(c)</td><td>Failure means X ≥ 4.</td><td>1</td></tr><tr><td>(c)</td><td>P(X ≥ 4) = 5(0.05)<sup>4</sup>(0.95) + (0.05)<sup>5</sup> = 0.00003.</td><td>1</td></tr><tr><td>(d)</td><td>Now Y ~ Bin(4, 0.05).</td><td>1</td></tr><tr><td>(d)</td><td>System works when Y ≤ 2.</td><td>1</td></tr><tr><td>(d)</td><td>P(Y ≤ 2) = 0.99951875 ≈ 0.9995.</td><td>1</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-ASSUMED-Q16":{"question":"<p>A milk machine fills bottles uniformly between 247 ml and 255 ml. The labelled amount is 250 ml.</p>","parts":[{"label":"(a)","text":"<p>Find the probability a randomly selected bottle contains less than the labelled amount.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Calculate the mean and standard deviation of bottle contents.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Bottles are selected one at a time. Find the probability the fifth bottle below the labelled amount is the 15th selected.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses uniform density 1/8 on [247, 255].</td><td>1</td></tr><tr><td>(a)</td><td>Computes interval length 250 − 247 = 3.</td><td>1</td></tr><tr><td>(a)</td><td>Probability = 3/8.</td><td>1</td></tr><tr><td>(b)</td><td>Mean is midpoint (247 + 255)/2.</td><td>1</td></tr><tr><td>(b)</td><td>Mean = 251 ml.</td><td>1</td></tr><tr><td>(b)</td><td>Variance = (255 − 247)<sup>2</sup>/12 = 16/3.</td><td>1</td></tr><tr><td>(b)</td><td>Standard deviation = 4/√3 ≈ 2.309 ml.</td><td>1</td></tr><tr><td>(c)</td><td>Requires exactly four low bottles in the first 14.</td><td>1</td></tr><tr><td>(c)</td><td>Multiplies by probability 3/8 for the 15th.</td><td>1</td></tr><tr><td>(c)</td><td>C(14, 4)(3/8)<sup>5</sup>(5/8)<sup>10</sup> ≈ 0.06751.</td><td>1</td></tr></tbody></table>","diagram":"","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2018-FREE-Q06":{"question":"<p>A company sells an item for $x. Profit per item is P(x) = 50ln(x/2)/x<sup>2</sup>, 1.5 ≤ x ≤ 10. Its graph is shown.</p>","parts":[{"label":"(a)","text":"<p>Describe how profit per item varies as the price changes.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the exact selling price maximising profit per item.</p>","marks":5,"lines":15,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Makes a loss for 1.5 ≤ x &lt; 2.</td><td>1</td></tr><tr><td>(a)</td><td>Profit rises to a maximum of about $2.30 at a selling price around $3.30.</td><td>1</td></tr><tr><td>(a)</td><td>Profit then decreases but stays positive up to x = 10.</td><td>1</td></tr><tr><td>(b)</td><td>Differentiates using quotient/product and chain rules.</td><td>1</td></tr><tr><td>(b)</td><td>P′(x) = 50[1 − 2ln(x/2)]/x<sup>3</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Sets 1 − 2ln(x/2) = 0.</td><td>1</td></tr><tr><td>(b)</td><td>Solves ln(x/2) = ½.</td><td>1</td></tr><tr><td>(b)</td><td>Optimal price $2√e, consistent with the maximum on the given interval.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2024-ASSUMED-Q11":{"question":"<p>A donut is generated by rotating the region (x − 3)<sup>2</sup> + y<sup>2</sup> ≤ 4 about the y-axis. Dimensions are centimetres.</p>","parts":[{"label":"(a)","text":"<p>Show the volume is ∫<sub>b</sub><sup>a</sup>12π√(4 − y<sup>2</sup>)dy, and state a and b.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Average density is 0.28 g/cm<sup>3</sup>. Calculate the maximum whole number of these donuts within the stated source limit of 180 g per day.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Circle gives x = 3 ± √(4 − y<sup>2</sup>).</td><td>1</td></tr><tr><td>(a)</td><td>Uses washers π[(3 + √(4 − y<sup>2</sup>))<sup>2</sup> − (3 − √(4 − y<sup>2</sup>))<sup>2</sup>].</td><td>1</td></tr><tr><td>(a)</td><td>Simplifies integrand to 12π√(4 − y<sup>2</sup>).</td><td>1</td></tr><tr><td>(a)</td><td>a = 2, b = −2.</td><td>1</td></tr><tr><td>(b)</td><td>Volume = 24π<sup>2</sup> cm<sup>3</sup>, giving mass 6.72π<sup>2</sup> ≈ 66.32 g.</td><td>1</td></tr><tr><td>(b)</td><td>180/66.32 ≈ 2.71; maximum whole number = 2.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-ASSUMED-Q15":{"question":"<p>A fair tetrahedral die labelled 1 to 4 is thrown twice. X is the sum of its two results.</p>","parts":[{"label":"(a)","text":"<p>Complete the sum table.</p><table><tr><th>First / second</th><th>1</th><th>2</th><th>3</th><th>4</th></tr><tr><td>1</td><td>2</td><td>3</td><td></td><td></td></tr><tr><td>2</td><td>3</td><td></td><td>5</td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td></tr></table><p></p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Complete the distribution.</p><table><tr><th>x</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8</th></tr><tr><td>P(X = x)</td><td>1/16</td><td></td><td></td><td></td><td></td><td></td><td>1/16</td></tr></table><p></p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>Find P(X ≤ 5).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)(iii)","text":"<p>Determine the mean and standard deviation of X.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Rows of sums: 2,3,4,5; 3,4,5,6; 4,5,6,7; 5,6,7,8.</td><td>1</td></tr><tr><td>(b)(i)</td><td>Probabilities for x = 2…8: 1,2,3,4,3,2,1 all divided by 16.</td><td>1</td></tr><tr><td>(b)(ii)</td><td>Adds first four probabilities.</td><td>1</td></tr><tr><td>(b)(ii)</td><td>Probability = 10/16 = 5/8.</td><td>1</td></tr><tr><td>(b)(iii)</td><td>Mean = 5.</td><td>1</td></tr><tr><td>(b)(iii)</td><td>Standard deviation = √(5/2) ≈ 1.581.</td><td>1</td></tr></tbody></table>","diagram":"","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2020-FREE-Q01":{"question":"<p>Ashley and Xavier use the spinner shown, where the result is the region under its stopped arrow.</p>","parts":[{"label":"(a)","text":"<p>If spun three times, find the probability that B never occurs.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>X is the number of B results in three spins. Complete its distribution.</p><table><tr><th>x</th><th>0</th><th>1</th><th>2</th><th>3</th></tr><tr><td>P(X = x)</td><td></td><td></td><td></td><td></td></tr></table><p></p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine the mean and variance of X.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>P(B) = 3/8, so probability of no B = (5/8)<sup>3</sup> = 125/512.</td><td>1</td></tr><tr><td>(b)</td><td>Recognises X ~ Bin(3, 3/8).</td><td>1</td></tr><tr><td>(b)</td><td>Uses C(3, x)(3/8)<sup>x</sup>(5/8)<sup>3−x</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Probabilities for 0,1,2,3: 125/512, 225/512, 135/512, 27/512.</td><td>1</td></tr><tr><td>(c)</td><td>Mean = 9/8.</td><td>1</td></tr><tr><td>(c)</td><td>Variance = 45/64.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2020-ASSUMED-Q13":{"question":"<p>Daily manufacturing cost, in hundreds of dollars, is C(x) = x ln(2x + 1)/3 − 2x + 120, with 0 ≤ x ≤ 200 components.</p>","parts":[{"label":"(a)","text":"<p>Determine the cost of manufacturing 20 components.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Sketch C(x).</p>","marks":3,"lines":9,"space":"drawing","diagram":""},{"label":"(c)","text":"<p>Using your graph, explain how many components should be manufactured daily to minimise total cost.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>C(20) ≈ 104.7571 hundreds, or $10475.71.</td><td>1</td></tr><tr><td>(b)</td><td>Correct domain 0 ≤ x ≤ 200.</td><td>1</td></tr><tr><td>(b)</td><td>C(0) = 120 and C(200) ≈ 119.60.</td><td>1</td></tr><tr><td>(b)</td><td>Shows a minimum between 70 and 80 with correct curve shape.</td><td>1</td></tr><tr><td>(c)</td><td>Continuous minimum at x ≈ 74.205.</td><td>1</td></tr><tr><td>(c)</td><td>Compares C(74) ≈ 95.4307 with C(75) ≈ 95.4320.</td><td>1</td></tr><tr><td>(c)</td><td>Manufacture 74 components for the lower cost.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-ASSUMED-Q11":{"question":"<p>Write equations or inequalities for the sketched loci in terms of z without using Re(z) or Im(z).</p>","parts":[{"label":"(a)","text":"<p>Describe the shaded circular region.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Describe the ray.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>For the locus in (a), determine the maximum arg(z) to 0.01, with 0 ≤ arg(z) &lt; 2π.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>|z − (1 − 2i)| ≤ 1; award for centre, radius and included interior.</td><td>3</td></tr><tr><td>(b)</td><td>arg(z − i) = 3π/4; award for translated vertex and direction.</td><td>2</td></tr><tr><td>(c)</td><td>Uses tangent from origin to the circle.</td><td>1</td></tr><tr><td>(c)</td><td>Centre distance √5 gives angular offset arcsin(1/√5).</td><td>1</td></tr><tr><td>(c)</td><td>Maximum argument = 2π − arctan 2 + arcsin(1/√5) ≈ 5.64 radians.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2017-ASSUMED-Q13":{"question":"<p>Traffic flow from F to H is shown in hundreds of cars per hour.</p>","parts":[{"label":"(a)","text":"<p>List paths and flow rates to determine maximum flow.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Show a minimum cut to verify it.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)(i)","text":"<p>Which single road should be widened to increase maximum flow most?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)(ii)","text":"<p>How much additional capacity should it have, and what would the new maximum flow be?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>One valid allocation: FJH 13; FCABEH 8; FGH 10; FGDEH 6; FCDBEH 10; FCDEH 2. Award for at least two correct paths, all paths, total and units.</td><td>4</td></tr><tr><td>(a)</td><td>Total = 49 hundreds = 4900 cars/hour.</td><td>0</td></tr><tr><td>(b)</td><td>Cut separating {F,C,A} from the remaining vertices crosses FJ, FG, CD and AB: 13 + 16 + 12 + 8 = 49.</td><td>1</td></tr><tr><td>(c)(i)</td><td>Widen FG, CD or AB (equally effective).</td><td>1</td></tr><tr><td>(c)(ii)</td><td>Increase the chosen road capacity by 3 hundreds = 300 cars/hour.</td><td>1</td></tr><tr><td>(c)(ii)</td><td>New maximum flow = 52 hundreds = 5200 cars/hour.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2021-FREE-Q02":{"question":"<p>Graphs of functions f and g are shown. The rule is f(x) = 2 − 2√(3 − x), −1 ≤ x ≤ 3.</p>","parts":[{"label":"(a)","text":"<p>Sketch f<sup>−1</sup> on the axes for f.</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Explain why g has no inverse function.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine the rule for f<sup>−1</sup>.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine g(f(0)) exactly.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Determine and justify the domain of f(g(x)).</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Reflects f in y = x as a concave-down curve.</td><td>1</td></tr><tr><td>(a)</td><td>Includes (−2, −1), (0, 2), (2, 3).</td><td>1</td></tr><tr><td>(b)</td><td>g is not one-to-one; it fails the horizontal line test.</td><td>1</td></tr><tr><td>(c)</td><td>Interchanges variables: x = 2 − 2√(3 − y).</td><td>1</td></tr><tr><td>(c)</td><td>Rearranges 3 − y = (2 − x)<sup>2</sup>/4.</td><td>1</td></tr><tr><td>(c)</td><td>f<sup>−1</sup>(x) = 3 − (2 − x)<sup>2</sup>/4, −2 ≤ x ≤ 2.</td><td>1</td></tr><tr><td>(d)</td><td>f(0) = 2 − 2√3.</td><td>1</td></tr><tr><td>(d)</td><td>Uses g(x) = x + 4 on this branch, giving 6 − 2√3.</td><td>1</td></tr><tr><td>(e)</td><td>Requires g(x) in [−1, 3].</td><td>1</td></tr><tr><td>(e)</td><td>Left branch gives −2 ≤ x ≤ −1.</td><td>1</td></tr><tr><td>(e)</td><td>Right branch gives ½ ≤ x ≤ 2; domain [−2, −1] ∪ [½, 2].</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2017-FREE-Q08":{"question":"<p>The inner surface of a glass is generated by rotating segment AB about the y-axis. Its bottom and top radii are a and b cm, and height h cm. Segment AB has y = h(x − a)/(b − a).</p>","parts":[{"label":"(a)","text":"<p>Write a definite integral for full volume.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Use an antiderivative to obtain a simplified volume formula in a, b and h.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Expresses radius x = a + (b − a)y/h.</td><td>1</td></tr><tr><td>(a)</td><td>V = π∫<sub>0</sub><sup>h</sup>[a + (b − a)y/h]<sup>2</sup>dy.</td><td>1</td></tr><tr><td>(b)</td><td>Expands or substitutes to integrate the square.</td><td>1</td></tr><tr><td>(b)</td><td>Evaluates the antiderivative at 0 and h.</td><td>1</td></tr><tr><td>(b)</td><td>V = πh(a<sup>2</sup> + ab + b<sup>2</sup>)/3.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":5,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2022-ASSUMED-Q11":{"question":"<p>An F1 car starts with displacement 192 m and velocity 24 m/second. For 11 seconds, velocity and displacement satisfy v(x) = x/8.</p>","parts":[{"label":"(a)","text":"<p>Determine acceleration a(x).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine displacement x(t).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Calculate the top speed and distance travelled during the 11 seconds.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses a = v dv/dx.</td><td>1</td></tr><tr><td>(a)</td><td>a(x) = x/64.</td><td>1</td></tr><tr><td>(b)</td><td>Solves dx/dt = x/8, obtaining x = Ce<sup>t/8</sup>.</td><td>1</td></tr><tr><td>(b)</td><td>Initial condition gives x(t) = 192e<sup>t/8</sup>.</td><td>1</td></tr><tr><td>(c)</td><td>Velocity v(t) = 24e<sup>t/8</sup> increases throughout.</td><td>1</td></tr><tr><td>(c)</td><td>Top speed = 24e<sup>11/8</sup> ≈ 94.922 m/second.</td><td>1</td></tr><tr><td>(c)</td><td>Distance = x(11) − x(0).</td><td>1</td></tr><tr><td>(c)</td><td>Distance = 192(e<sup>11/8</sup> − 1) ≈ 567.374 m.</td><td>1</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2020-ASSUMED-Q09":{"question":"<p>Daily birthday-cake demand X has distribution:</p><table><tr><th>x</th><th>0</th><th>1</th><th>2</th><th>3</th><th>4</th></tr><tr><td>P(X = x)</td><td>0.1</td><td>0.2</td><td>0.25</td><td>0.35</td><td>0.1</td></tr></table><p></p>","parts":[{"label":"(a)","text":"<p>Calculate mean cakes sold per day.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>On Monday four cakes are made at $20 each and sold for $50 each. Find expected profit or loss.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>On Tuesday three cakes are made. Y is the number unsold. Explain P(Y = 0) = 0.45.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Obtain the distribution of Y.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Mean = 2.15.</td><td>1</td></tr><tr><td>(b)</td><td>Fixed cost = 4 × $20 = $80.</td><td>1</td></tr><tr><td>(b)</td><td>Expected revenue = $50 × 2.15 = $107.50.</td><td>1</td></tr><tr><td>(b)</td><td>Expected profit = $27.50.</td><td>1</td></tr><tr><td>(c)</td><td>No cakes remain when demand is at least three.</td><td>1</td></tr><tr><td>(c)</td><td>P(Y = 0) = P(X = 3) + P(X = 4) = 0.35 + 0.1 = 0.45.</td><td>1</td></tr><tr><td>(d)</td><td>Y takes values 0, 1, 2, 3.</td><td>1</td></tr><tr><td>(d)</td><td>Probabilities are 0.45, 0.25, 0.2, 0.1 respectively.</td><td>1</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2020-ASSUMED-Q11":{"question":"<p>The line y = x + c is tangent to f(x) = e<sup>x</sup>.</p>","parts":[{"label":"(a)","text":"<p>Obtain the tangent point coordinates.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine c.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Sketch f and the tangent.</p>","marks":1,"lines":8,"space":"drawing","diagram":""},{"label":"(d)","text":"<p>Evaluate the exact area between f, the tangent and x = ln 2.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(e)","text":"<p>If g is the inverse of f, write a definite integral for the area bounded by g, the x-axis and x = ln 2.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Matches derivative e<sup>x</sup> to slope 1, giving x = 0.</td><td>1</td></tr><tr><td>(a)</td><td>Tangent point (0, 1).</td><td>1</td></tr><tr><td>(b)</td><td>c = 1.</td><td>1</td></tr><tr><td>(c)</td><td>Shows exponential and tangent y = x + 1 touching at (0, 1).</td><td>1</td></tr><tr><td>(d)</td><td>Sets ∫<sub>0</sub><sup>ln 2</sup>(e<sup>x</sup> − x − 1)dx.</td><td>1</td></tr><tr><td>(d)</td><td>Antiderivative e<sup>x</sup> − x<sup>2</sup>/2 − x.</td><td>1</td></tr><tr><td>(d)</td><td>Area = 1 − ln 2 − (ln 2)<sup>2</sup>/2.</td><td>1</td></tr><tr><td>(e)</td><td>Recognises g(x) = ln x, below x-axis for ln 2 ≤ x ≤ 1.</td><td>1</td></tr><tr><td>(e)</td><td>Area = −∫<sub>ln 2</sub><sup>1</sup>ln x dx (or reversed limits without minus).</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true}});
